// Input: an n8n workflow as JSON text. Output: plain-language problems.
let wf;
try { wf = JSON.parse(query); } catch (e) { return 'That is not valid JSON. In n8n, select all nodes (Ctrl+A), copy (Ctrl+C) and pass the copied text.'; }
if (wf.data && wf.data.nodes) wf = wf.data;
if (Array.isArray(wf)) wf = wf[0];
const nodes = wf.nodes || [];
const KEYS = [/sk-(?:proj-)?[A-Za-z0-9_-]{24,}/, /sk-ant-[A-Za-z0-9_-]{20,}/, /[sr]k_live_[A-Za-z0-9]{16,}/, /AKIA[0-9A-Z]{16}/, /gh[pousr]_[A-Za-z0-9]{30,}/, /AIza[0-9A-Za-z_-]{35}/, /apify_api_[A-Za-z0-9]{20,}/, /xox[bp]-[A-Za-z0-9-]{20,}/];
const ACTION = /gmail|slack|googleSheets|airtable|notion|postgres|supabase|telegram|discord|httpRequest|hubspot|microsoftOutlook/i;
const out = [];
for (const n of nodes) {
  if (n.disabled || /stickyNote/.test(n.type)) { if (n.disabled) out.push(`"${n.name}" is turned off but still in the workflow. Delete it once things work.`); continue; }
  const p = JSON.stringify(n.parameters || {});
  const auth = n.parameters?.authentication;
  if (KEYS.some(r => r.test(p))) out.push(`Key typed straight into "${n.name}". Move it into an n8n credential, then make a new key and delete the old one.`);
  if (/\.webhook$/i.test(n.type) && (!auth || auth === 'none')) out.push(`Webhook "${n.name}" has no authentication. Set Authentication to Header Auth.`);
  if (/mcpTrigger/i.test(n.type) && (!auth || auth === 'none')) out.push(`MCP server "${n.name}" has no authentication. Anyone with the URL can call its tools. Set Bearer Auth.`);
  if (/chatTrigger/i.test(n.type) && n.parameters?.public) out.push(`Chat "${n.name}" is public. Anyone can spend your AI credits.`);
}
for (const [from, c] of Object.entries(wf.connections || {})) for (const group of (c.ai_tool || [])) for (const t of group) {
  const tool = nodes.find(n => n.name === from);
  const target = nodes.find(n => n.name === t.node);
  if (target && /mcpTrigger/i.test(target.type)) continue; // MCP clients ask the user before each call
  if (tool && !tool.disabled && ACTION.test(tool.type) && !/^(get|getAll|search|read|list)$/i.test(String(tool.parameters?.operation || ''))) out.push(`AI agent "${t.node}" can use "${from}" on its own. Add a human approval step before it sends or changes anything.`);
}
if (!wf.settings?.errorWorkflow) out.push('No error workflow. If this breaks, nobody hears about it. Add one in workflow settings.');
const score = Math.max(0, 100 - out.length * 15);
return out.length ? `Flowscope health score ${score}/100 for "${wf.name || 'this workflow'}" (${nodes.length} nodes). ${out.length} thing${out.length > 1 ? 's' : ''} to fix:\n` + out.map((o, i) => `${i + 1}. ${o}`).join('\n') : `Flowscope health score 100/100 for "${wf.name || 'this workflow'}". Nothing to fix.`;

// Input: code or a git diff. Output: leaked keys by line. Never repeats the key itself.
const RULES = [
  [/sk-(?:proj-)?[A-Za-z0-9_-]{24,}/, 'OpenAI key'], [/sk-ant-[A-Za-z0-9_-]{20,}/, 'Anthropic key'], [/[sr]k_live_[A-Za-z0-9]{16,}/, 'Stripe live key'],
  [/AKIA[0-9A-Z]{16}/, 'AWS access key'], [/gh[pousr]_[A-Za-z0-9]{30,}/, 'GitHub token'], [/AIza[0-9A-Za-z_-]{35}/, 'Google API key'],
  [/apify_api_[A-Za-z0-9]{20,}/, 'Apify token'], [/xox[bp]-[A-Za-z0-9-]{20,}/, 'Slack token'],
  [/(VITE_|NEXT_PUBLIC_|REACT_APP_|EXPO_PUBLIC_)\w*(SECRET|SERVICE_ROLE|OPENAI|ANTHROPIC|STRIPE_SECRET|RESEND)/, 'secret read in browser code'],
  [/dangerouslyAllowBrowser\s*:\s*true/, 'AI SDK allowed in the browser'],
];
const found = [];
String(query || '').split('\n').forEach((ln, i) => { if (ln.startsWith('-')) return; for (const [re, what] of RULES) if (re.test(ln)) found.push(`Line ${i + 1}: ${what}`); });
return found.length ? `Flowscope found ${found.length} problem${found.length > 1 ? 's' : ''}:\n${found.join('\n')}\n\nFix: make a new key in that service and delete the old one, move it into .env, and read it only in server code.` : 'Flowscope found no leaked keys in this code.';
